import java.io.*;
import java.util.*;

public class ll {
    public static void main(String[] args) throws IOException {
        new gg();
    }
}

class gg {
    gg() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine());
        char[] word = br.readLine().toCharArray();
        String[] parts = br.readLine().split(" ");
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) vals[i] = Integer.parseInt(parts[i]);
        int[] badones = new int[26];
        int m = 0;
        for (int i = 0; i < n / 2; i++) {
            if (word[i] == word[n - i - 1]) {
                badones[word[i] - 'a']++;
                m++;
            }
        }
        boolean bad = false;
        int val = -1;
        for (int i = 0; i < 26; i++) {
            if (badones[i] * 2 > m) {
                bad = true;
                val = i;
            }
        }
        if (!bad) {
            long sum = 0;
            for (int i = 0; i < n / 2; i++) {
                if (word[i] != word[n - i - 1])
                    sum += vals[i] + vals[n - i - 1];
                else
                    sum += Math.max(vals[i], vals[n - i - 1]);
            }
            pw.println(sum);
        } else {
            int others = badones[val] - (m - badones[val]);
            PriorityQueue<Integer> pq = new PriorityQueue<>();
            for (int i = 0; i < n / 2; i++) {
                if (word[i] != word[n - i - 1] && word[i] != 'a' + val && word[n - i - 1] != 'a' + val)
                    pq.add(Math.min(vals[i], vals[n - i - 1]));
            }
            long ans = 0;
            for (int i = 0; i < n / 2; i++) {
                if (word[i] == word[n - i - 1])
                    ans += Math.max(vals[i], vals[n - i - 1]);
                else
                    ans += vals[i] + vals[n - i - 1];
            }
            for (int i = 0; i < others; i++)
                ans -= pq.poll();
            pw.println(ans);
        }
        pw.close();
    }
}
